<template><ElConfigProvider :locale="zh" size="large">
 <div v-if="booting" class="v1-login"><ElCard shadow="never"><ElSkeleton :rows="4" animated /><ElButton v-if="fatal" class="v1-gap" @click="boot">重新连接</ElButton></ElCard></div>
 <div v-else-if="!session?.user" class="v1-login"><ElCard><h1>天枢 · v1.0</h1><ArtForm v-model="credentials" :items="loginFields" :span="24" label-position="top" :show-reset="false" :show-submit="false" /><ElAlert v-if="fatal" :title="fatal" type="error" :closable="false" /><ElButton type="primary" class="v1-full" :loading="busy" @click="login">登录</ElButton></ElCard></div>
 <div v-else class="v1-shell"><aside class="v1-sidebar"><ArtSidebarMenu /></aside><div class="v1-main" :style="{marginLeft:setting.menuOpen?setting.menuOpenWidth+'px':'70px'}"><header class="v1-header"><ElSpace><ArtIconButton icon="ri:menu-2-line" aria-label="折叠菜单" @click="setting.setMenuOpen(!setting.menuOpen)" /><ElBreadcrumb><ElBreadcrumbItem>天枢 v1.0</ElBreadcrumbItem><ElBreadcrumbItem>{{title}}</ElBreadcrumbItem></ElBreadcrumb></ElSpace><ElSpace><ElTag :type="snapshot?.collector_healthy?'success':'danger'">{{snapshot?.collector_healthy?'采集正常':'采集异常'}}</ElTag><ArtIconButton :icon="setting.isDark?'ri:sun-line':'ri:moon-line'" aria-label="切换主题" @click="theme.switchThemeStyles(setting.isDark?'light':'dark')" /><ArtIconButton icon="ri:settings-3-line" aria-label="界面设置" @click="appearance=true" /><ElDropdown @command="profile"><ElButton text>{{session.user.username}}<ArtSvgIcon icon="ri:arrow-down-s-line" /></ElButton><template #dropdown><ElDropdownMenu><ElDropdownItem command="settings">后端设置</ElDropdownItem><ElDropdownItem v-if="session.user.role!=='demo'" command="logout">退出登录</ElDropdownItem></ElDropdownMenu></template></ElDropdown></ElSpace></header>
 <main class="v1-content"><ElCard shadow="never" class="v1-meta"><ElSpace class="v1-spread"><ElSpace><ElSelect v-model="spaceId" aria-label="用电空间" style="width:250px"><ElOption v-for="s in spaces" :key="s.id" :value="s.id" :label="s.name" /></ElSelect><ElButton v-if="admin" circle aria-label="新建空间" @click="spaceOpen=true"><ArtSvgIcon icon="ri:add-line" /></ElButton></ElSpace><ElSpace><ElTag v-if="snapshot?.source==='simulated'" type="warning">演示空间</ElTag><ElTooltip :content="date(snapshot?.heartbeat)"><ElButton text circle aria-label="采集时间"><ArtSvgIcon icon="ri:time-line" /></ElButton></ElTooltip><ElButton @click="refresh">刷新</ElButton></ElSpace></ElSpace></ElCard>
 <ElAlert v-if="fatal" :title="fatal" type="error" show-icon :closable="false" class="v1-meta" />
 <template v-if="snapshot&&currentSpace">
  <V1Overview v-if="page==='overview'" :key="spaceId" :snapshot="snapshot" :reports="reports" @navigate="go" />
  <V1Devices v-else-if="['facilities','meters'].includes(page)" :key="spaceId+'-'+page" :mode="page" :space-id="spaceId" :devices="snapshot.devices" :user="session.user" :gateways="gateways.filter(g=>g.space_id===spaceId)" @refresh="refresh" @control="control" @navigate="go" />
  <PredictionCenter v-else-if="page==='prediction'" :key="spaceId" :space-id="spaceId" :reports="reports" :days="days" @range="range" @navigate="go" />
  <V1Alerts v-else-if="page==='alerts'" :key="spaceId" :space-id="spaceId" :devices="snapshot.devices" :user="session.user" @navigate="go" />
  <V1Settings v-else-if="page==='settings'" :key="spaceId+'-'+session.user.role" :space="currentSpace" :user="session.user" @refresh="refresh" @session="boot" @navigate="go" />
  <V1Cameras v-else-if="page==='cameras'" :key="spaceId" :space-id="spaceId" :cameras="cameras" :user="session.user" @refresh="refresh" />
  <ElCard v-else-if="page==='audit'" shadow="never"><template #header>操作审计</template><ArtTable :data="audit" height="600" :show-table-header="false"><ElTableColumn label="时间" min-width="180"><template #default="{row}">{{date(row.ts)}}</template></ElTableColumn><ElTableColumn prop="actor" label="账户" /><ElTableColumn prop="action" label="操作" /><ElTableColumn prop="target" label="目标" /><ElTableColumn prop="detail" label="详情" min-width="250" show-overflow-tooltip /></ArtTable></ElCard>
 </template><ElEmpty v-else description="暂无空间数据" />
 </main></div><ArtPreferences v-model="appearance" :status="preferences.status.value" /></div>
 <ElDrawer v-model="spaceOpen" title="新增用电空间" direction="rtl" size="min(460px,100vw)"><ArtForm v-model="spaceDraft" :items="[{key:'name',label:'空间名称',type:'input'}]" :span="24" label-position="top" :show-submit="false" :show-reset="false" /><ElAlert v-if="spaceError" :title="spaceError" type="error" :closable="false" /><template #footer><ElButton @click="spaceOpen=false">取消</ElButton><ElButton type="primary" :loading="busy" @click="saveSpace">创建</ElButton></template></ElDrawer>
 <ElDialog v-model="controlOpen" :title="controlTarget?.relay_on?'远程断电':'恢复供电'" width="min(660px,94vw)" :close-on-click-modal="false" :close-on-press-escape="!busy" align-center><ElSpace v-if="controlTarget" direction="vertical" fill :size="20" class="v1-dialog-stack"><ElAlert :title="controlTarget.relay_on?'确认目标及受影响设施':'确认现场允许恢复供电'" :type="controlTarget.relay_on?'error':'warning'" show-icon :closable="false" /><ElDescriptions :column="1" border><ElDescriptionsItem label="目标">{{controlTarget.name}}</ElDescriptionsItem><ElDescriptionsItem label="区域">{{controlTarget.area}}</ElDescriptionsItem></ElDescriptions><ArtTable v-if="impact.length" :data="impact" :show-table-header="false" height="180"><ElTableColumn prop="name" label="受影响设施" /><ElTableColumn label="保护"><template #default="{row}">{{row.protected?'是':'否'}}</template></ElTableColumn></ArtTable><ArtForm v-model="controlDraft" :items="[{key:'reason',label:'操作原因',type:'input',props:{type:'textarea',rows:3}},{key:'confirm_name',label:'输入完整设备名称',type:'input'}]" :span="24" label-position="top" :show-submit="false" :show-reset="false" /><ElAlert v-if="controlError" :title="controlError" type="error" :closable="false" /></ElSpace><template #footer><ElButton :disabled="busy" @click="controlOpen=false">取消</ElButton><ElButton :type="controlTarget?.relay_on?'danger':'primary'" :loading="busy" :disabled="controlDraft.confirm_name!==controlTarget?.name||!controlDraft.reason||(controlTarget?.relay_on&&impact.some(d=>d.protected))" @click="sendControl">确认执行</ElButton></template></ElDialog>
</ElConfigProvider></template>
<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount,provide} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import zh from 'element-plus/es/locale/lang/zh-cn';import {api,setCsrf,date} from './api';import {useSettingStore} from './art/store/modules/setting';import {useMenuStore} from './art/store/modules/menu';import {initializeTheme,useTheme} from './art/hooks/core/useTheme';import ArtSidebarMenu from './art/components/core/layouts/art-menus/art-sidebar-menu/index.vue';import ArtIconButton from './art/components/core/widget/art-icon-button/index.vue';import ArtPreferences from './ArtPreferences.vue';import {usePreferences} from './preferences';import V1Devices from './V1Devices.vue';import V1Overview from './V1Overview.vue';import PredictionCenter from './PredictionCenter.vue';import V1Alerts from './V1Alerts.vue';import V1Settings from './V1Settings.vue';import V1Cameras from './V1Cameras.vue';
const route=useRoute(),router=useRouter(),setting=useSettingStore(),menu=useMenuStore();initializeTheme();const theme=useTheme(),appearance=ref(false),brand=ref({});provide('energyBrand',brand);
const nav=[{key:'overview',title:'运行大屏',icon:'ri:dashboard-line'},{key:'prediction',title:'预测中心',icon:'ri:line-chart-line'},{key:'facilities',title:'设施与回路',icon:'ri:plug-line'},{key:'meters',title:'智能电表',icon:'ri:dashboard-3-line'},{key:'cameras',title:'监控画面',icon:'ri:vidicon-line'},{key:'alerts',title:'告警中心',icon:'ri:alarm-warning-line'},{key:'audit',title:'操作审计',icon:'ri:file-list-3-line'},{key:'settings',title:'后端设置',icon:'ri:settings-3-line'}];const entry=k=>{const n=nav.find(n=>n.key===k);return {path:'/'+k,name:k,component:'energy/'+k,meta:{title:'energy.nav.'+k,icon:n.icon,isFirstLevel:true}}};menu.setMenuList([entry('overview'),{path:'/device-center',name:'device-center',meta:{title:'energy.nav.devices',icon:'ri:plug-line'},children:[entry('facilities'),entry('meters')]},...['prediction','alerts','cameras','audit','settings'].map(entry)]);
const session=ref(null),booting=ref(true),busy=ref(false),fatal=ref(''),spaces=ref([]),spaceId=ref(''),snapshot=shallowRef(null),reports=ref(null),cameras=ref([]),gateways=ref([]),days=ref(7),audit=ref([]);const page=computed(()=>route.name||'overview'),title=computed(()=>nav.find(n=>n.key===page.value)?.title||'天枢'),currentSpace=computed(()=>snapshot.value?.space||spaces.value.find(s=>s.id===spaceId.value)),admin=computed(()=>['admin','demo'].includes(session.value?.user?.role));const preferences=usePreferences(()=>session.value?.user);const credentials=ref({username:'',password:''}),loginFields=[{key:'username',label:'账户',type:'input',props:{autocomplete:'username'}},{key:'password',label:'密码',type:'input',props:{type:'password',showPassword:true,autocomplete:'current-password'}}];let stream,timer,run=0;
function go(key){router.push('/'+key)}async function profile(key){if(key==='settings')go(key);else{await api('logout',{});await boot()}}
async function boot(){booting.value=true;stream?.close();try{session.value=await api('session');setCsrf(session.value.csrf||'');if(session.value.user){await preferences.load();spaces.value=(await api('spaces')).spaces;if(!spaces.value.some(s=>s.id===spaceId.value))spaceId.value=spaces.value[0]?.id||'';await refresh();startStream()}}catch(e){fatal.value=e.message}finally{booting.value=false}}
async function login(){busy.value=true;try{await api('login',credentials.value);credentials.value.password='';await boot()}catch(e){fatal.value=e.message}finally{busy.value=false}}
async function refresh(){if(!spaceId.value||!session.value?.user)return;const sid=spaceId.value,id=++run;try{const [s,r,c,sys]=await Promise.all([api('snapshot?space_id='+sid),api('reports?space_id='+sid+'&days='+days.value),api('cameras?space_id='+sid),api('system')]);if(id!==run)return;snapshot.value=s;reports.value=r;cameras.value=c.cameras;gateways.value=sys.gateways||[];spaces.value=spaces.value.map(x=>x.id===sid?s.space:x);fatal.value='';brand.value=(await api('brand')).settings;if(page.value==='audit')audit.value=(await api('audit')).audit}catch(e){fatal.value=e.message;if(e.status===401){session.value={user:null};stream?.close()}}}
function startStream(){stream?.close();if(!spaceId.value)return;const sid=spaceId.value;stream=new EventSource('/api/stream?space_id='+sid);stream.addEventListener('snapshot',event=>{if(spaceId.value===sid)try{snapshot.value=JSON.parse(event.data)}catch{}});stream.onerror=()=>{if(snapshot.value)snapshot.value={...snapshot.value,collector_healthy:false}}}
async function range(value){days.value=value;await refresh()}
const spaceOpen=ref(false),spaceDraft=ref({name:''}),spaceError=ref('');async function saveSpace(){busy.value=true;try{const s=await api('spaces',spaceDraft.value);spaces.value=(await api('spaces')).spaces;spaceOpen.value=false;spaceDraft.value={name:''};spaceId.value=s.id}catch(e){spaceError.value=e.message}finally{busy.value=false}}
const controlTarget=ref(null),controlOpen=ref(false),controlDraft=ref({}),impact=ref([]),controlError=ref('');let commandKey;
async function control(d){try{impact.value=(await api('impact?device_id='+d.id)).devices;controlTarget.value={...d};controlDraft.value={reason:'',confirm_name:''};controlError.value='';commandKey=crypto.randomUUID();controlOpen.value=true}catch(e){ElMessage.error(e.message)}}
async function sendControl(){busy.value=true;try{await api('command',{...controlDraft.value,device_id:controlTarget.value.id,desired:!controlTarget.value.relay_on,idempotency:commandKey});controlOpen.value=false;ElMessage.info('指令已发送，等待执行回执');await refresh()}catch(e){controlError.value=e.message}finally{busy.value=false}}
watch(spaceId,async(value,old)=>{if(value&&old&&value!==old){snapshot.value=null;await refresh();startStream()}});watch(page,()=>{document.title=title.value+' · 天枢 v1.0';if(page.value==='audit')refresh()});onMounted(()=>{boot();timer=setInterval(()=>{if(!document.hidden&&session.value?.user)refresh()},15000)});onBeforeUnmount(()=>{stream?.close();clearInterval(timer)});
</script>
